const fs=require('fs'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
function load(name,mobile){const dom=new JSDOM(fs.readFileSync('students/'+name+'.html','utf8'),{url:'https://example.test/students/'+name+'.html',runScripts:'outside-only'}),w=dom.window;w.matchMedia=()=>({matches:mobile,addEventListener(){}});w.scrollTo=()=>{};w.eval(fs.readFileSync('students/teaching-view.js','utf8'));return dom}
for(const name of ['labs','examples','explorers','cargo','mollier'])for(const mobile of [true,false]){const dom=load(name,mobile),w=dom.window,d=w.document;assert.ok(d.querySelector('.teaching-inputs'));for(const x of d.querySelectorAll('.teaching-inputs'))assert.equal(x.open,!mobile);const input=d.querySelector('input:not([type=file])');if(input)input.value='123';const svg=d.querySelector('svg'),button=d.getElementById('presentation-toggle');button.click();assert.ok(d.body.classList.contains('presentation-view'));assert.equal(button.getAttribute('aria-pressed'),'true');assert.equal(d.querySelector('svg'),svg);w.document.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape'}));assert.ok(!d.body.classList.contains('presentation-view'));if(input)assert.equal(input.value,'123');dom.window.close()}
const dom=load('cargo',true),d=dom.window.document;assert.ok(d.getElementById('results').closest('section').compareDocumentPosition(d.querySelector('.teaching-inputs'))&4);assert.ok(d.querySelector('.teaching-inputs #preset'));dom.window.close();
const e=load('examples',false).window;e.eval(fs.readFileSync('students/study-export.js','utf8'));const E=e.MT_STUDY_EXPORT,raw=2777.119537643596,s={model:'test',title:'Precision',inputs:{x:.000000123456789},results:{h:raw,negativeZero:-0},tables:[{title:'Raw table',rows:[['h'],[raw]]}]};const html=E.report(s),r=new JSDOM(html).window.document;assert.equal(r.querySelector('script').textContent.includes(String(raw)),true);assert.equal(JSON.parse(r.querySelector('script').textContent).results.h,raw);assert.equal(r.querySelector('h2:nth-of-type(2)+p+table td').textContent,'2777.12');assert.equal(E.displayValue(-0),'0');assert.equal(E.displayValue(1.23456789e-7),'1.23457e-7');assert.ok(E.csv([[raw]]).includes(String(raw)));e.close();console.log('PASS: teaching layout, presentation state/exit, preserved forms and precision-safe report formatting');
